description:
Implement a `useFocus` hook that returns a `[ref, isFocused]` tuple. Attach the ref to a focusable element and `isFocused` will be `true` while that element has focus.

**Example:**
```tsx
const [ref, isFocused] = useFocus();
return <input ref={ref} placeholder={isFocused ? 'Typing...' : 'Click me'} />;
```

starter_code:
import { useEffect, useRef, useState } from 'react';

export function useFocus<T extends Element>(): [React.RefObject<T>, boolean] {
  // your code here
}

test_suite:
test('isFocused is false initially', () => {
  const { result } = renderHook(() => useFocus());
  expect(result.current[1]).toBe(false);
});

test('isFocused is true after focus event', () => {
  const { result } = renderHook(() => useFocus());
  const input = document.createElement('input');
  result.current[0].current = input;
  act(() => input.dispatchEvent(new FocusEvent('focus')));
  expect(result.current[1]).toBe(true);
});

test('isFocused is false after blur event', () => {
  const { result } = renderHook(() => useFocus());
  const input = document.createElement('input');
  result.current[0].current = input;
  act(() => input.dispatchEvent(new FocusEvent('focus')));
  act(() => input.dispatchEvent(new FocusEvent('blur')));
  expect(result.current[1]).toBe(false);
});

// __hidden__
test('listener removed on unmount', () => {
  const { result, unmount } = renderHook(() => useFocus());
  const input = document.createElement('input');
  result.current[0].current = input;
  unmount();
  act(() => input.dispatchEvent(new FocusEvent('focus')));
  expect(result.current[1]).toBe(false);
});

solution:
import { useEffect, useRef, useState } from 'react';

export function useFocus<T extends Element>(): [React.RefObject<T>, boolean] {
  const ref = useRef<T>(null);
  const [isFocused, setIsFocused] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const onFocus = () => setIsFocused(true);
    const onBlur = () => setIsFocused(false);
    el.addEventListener('focus', onFocus);
    el.addEventListener('blur', onBlur);
    return () => {
      el.removeEventListener('focus', onFocus);
      el.removeEventListener('blur', onBlur);
    };
  }, []);

  return [ref, isFocused];
}
